function teamInjurySnapshot(ids){return ids.flatMap(id=>{const club=state.teams[id];return club.roster.filter(p=>injuryDays(p)>0).map(p=>({id:p.id,text:p.name+' · '+club.city+' '+club.name+' · '+medicalLabel(p)+' · Expected recovery: '+injuryDays(p)+' days'}))})}
const playBeforeInjuryReports=play;
play=function(a,b,stage='Regular season'){const before=teamInjurySnapshot([a,b]),result=playBeforeInjuryReports(a,b,stage),previous=new Set(before.map(p=>p.id)),after=teamInjurySnapshot([a,b]);result.injuryReport=[...before.map(p=>'Unavailable at tip-off: '+p.text),...after.filter(p=>!previous.has(p.id)).map(p=>'New injury: '+p.text)];return result};
function gameInjuryLines(result,pair){if(result)return result.injuryReport??(result.rotationEvents||[]).filter(line=>line.startsWith('MEDICAL: ')).map(line=>line.slice(9));return teamInjurySnapshot(pair).map(p=>p.text)}
function scheduleInjuryField(day,pair,result){const lines=gameInjuryLines(result,pair);return `<div class="schedule-injury"><small>Injury report</small>${lines.length?`<button class="namebutton" onclick="viewGameInjuries(${day},${pair[0]},${pair[1]})">View injury report</button>`:'<span class="muted">None</span>'}</div>`}
function viewGameInjuries(day,a,b){const result=state.history.find(g=>g.day===day&&g.stage==='Regular season'&&g.a===a&&g.b===b),lines=gameInjuryLines(result,[a,b]);titleModal('Injury report',`<p>${escapeHTML(state.teams[a].city+' '+state.teams[a].name)} vs ${escapeHTML(state.teams[b].city+' '+state.teams[b].name)} · ${scheduleDateLabel(day,true)}</p><p class="muted">${result?result.injuryReport?'Injuries recorded at tip-off and new injuries from this game. Recovery estimates are as recorded on game day.':'This older game includes only injuries recorded in its medical event log.':'Current injury status for both teams. Availability may change before this scheduled game.'}</p>${lines.length?'<ul class="game-injury-list">'+lines.map(line=>'<li>'+escapeHTML(line)+'</li>').join(''):'<p>None</p>'}`)}
function readGameInjuryReport(raw,bad){if(raw===undefined)return undefined;if(!Array.isArray(raw)||raw.length>60||raw.some(line=>typeof line!=='string'||line.length>600))bad('invalid game injury report');return [...raw]}
